<template id="purchase-row"><tr><td class="min-w-[260px]"><input type="search" list="purchase-products" class="field" data-product-search placeholder="Type product, SKU or barcode" required><input type="hidden" data-product-id><div data-batch-msg class="mt-1 text-xs empty:hidden"></div></td><td data-sku class="text-xs text-slate-500">—</td><td data-stock>0</td><td><input type="number" min=".01" step="any" value="1" class="field !w-24" data-qty required></td><td><input type="number" min="0" step=".01" class="field !w-28" data-cost required></td><td><input type="number" min="0" step=".01" class="field !w-28" data-selling required></td><td><input type="number" min="0" step=".01" value="0" class="field !w-24" data-discount></td><td class="font-black" data-line>Rs. 0.00</td><td><button type="button" class="rounded-lg bg-red-50 px-3 py-2 font-black text-red-600" data-remove>×</button></td></tr></template><datalist id="purchase-products">@foreach($productOptions as $option)<option value="{{ $option['label'] }}"></option>@endforeach</datalist>
<script>(()=>{const form=document.getElementById('purchase-form');const products={{ Illuminate\Support\Js::from($productOptions) }};const body=form.querySelector('[data-items]');const template=document.getElementById('purchase-row');const storeSelect=form.querySelector('[name="store_id"]');const money=n=>'Rs. '+Number(n||0).toFixed(2);const checkBatch=(row, product)=>{if(!product)return;const cost=+(row.querySelector('[data-cost]').value||0);const selling=+(row.querySelector('[data-selling]').value||0);const msg=row.querySelector('[data-batch-msg]');const storeId=+storeSelect.value;if(!storeId){msg.textContent='';return;}const exists=product.batches&&product.batches.some(b=>b.store_id===storeId&&b.cost===cost&&b.selling===selling);if(exists){msg.textContent='Quantity will be added to existing batch.';msg.className='mt-1 text-xs font-bold text-emerald-600';}else{msg.textContent='New batch will be created because price changed.';msg.className='mt-1 text-xs font-bold text-indigo-600';}};const calculate=()=>{let subtotal=0;body.querySelectorAll('tr').forEach(row=>{const total=Math.max(0,(+row.querySelector('[data-qty]').value||0)*(+row.querySelector('[data-cost]').value||0)-(+row.querySelector('[data-discount]').value||0));row.querySelector('[data-line]').textContent=money(total);subtotal+=total;const hidden=row.querySelector('[data-product-id]');if(hidden.value){const product=products.find(p=>p.id==hidden.value);checkBatch(row, product);}});const grand=Math.max(0,subtotal-(+form.discount.value||0)+(+form.tax.value||0)+(+form.other_cost.value||0));const rows=Array.from(form.querySelectorAll('[name$="[amount]"]'));const paid=rows.filter(i=>!['Cheque','Party Cheque'].includes(form.querySelector('[name="'+i.name.replace('[amount]','[method]')+'"]').value)).reduce((n,i)=>n+(+i.value||0),0);const hold=rows.reduce((n,i)=>n+(+i.value||0),0)-paid;form.querySelector('[data-hold]').textContent=money(hold);form.querySelector('[data-subtotal]').textContent=money(subtotal);form.querySelector('[data-grand]').textContent=money(grand);form.querySelector('[data-paid]').textContent=money(paid);form.querySelector('[data-due]').textContent=money(Math.max(0,grand-paid-hold));};const addRow=()=>{const row=template.content.firstElementChild.cloneNode(true);const index=body.children.length;const search=row.querySelector('[data-product-search]');const hidden=row.querySelector('[data-product-id]');hidden.name=`items[${index}][product_id]`;row.querySelector('[data-qty]').name=`items[${index}][quantity]`;row.querySelector('[data-cost]').name=`items[${index}][cost_price]`;row.querySelector('[data-selling]').name=`items[${index}][selling_price]`;row.querySelector('[data-discount]').name=`items[${index}][discount]`;search.addEventListener('input',()=>{const product=products.find(p=>p.label.toLowerCase()===search.value.trim().toLowerCase());hidden.value=product?.id||'';search.setCustomValidity(search.value&&!product?'Choose a product from the suggestions.':'');row.querySelector('[data-sku]').textContent=product?(product.sku+(product.barcode?' / '+product.barcode:'')):'—';row.querySelector('[data-stock]').textContent=product?.stock??0;row.querySelector('[data-cost]').value=product?.cost??'';row.querySelector('[data-selling]').value=product?.selling??'';calculate()});row.querySelectorAll('input').forEach(input=>input.addEventListener('input',calculate));row.querySelector('[data-remove]').addEventListener('click',()=>{row.remove();renumber();calculate()});body.append(row);calculate();};const renumber=()=>body.querySelectorAll('tr').forEach((row,i)=>{row.querySelector('[data-product-id]').name=`items[${i}][product_id]`;row.querySelector('[data-qty]').name=`items[${i}][quantity]`;row.querySelector('[data-cost]').name=`items[${i}][cost_price]`;row.querySelector('[data-selling]').name=`items[${i}][selling_price]`;row.querySelector('[data-discount]').name=`items[${i}][discount]`});form.querySelector('[data-add-row]').addEventListener('click',addRow);form.querySelector('[data-scan]').addEventListener('click',()=>{if(!body.children.length)addRow();body.lastElementChild.querySelector('[data-product-search]').focus()});form.querySelectorAll('[data-total-input]').forEach(input=>input.addEventListener('input',calculate));storeSelect.addEventListener('change', calculate);form.addEventListener('input',calculate);form.addEventListener('change',calculate);form.addEventListener('split-payment-change',()=>setTimeout(calculate,0));addRow();})();</script></div></x-layouts::app>
